import json, sys
from collections import defaultdict

def alt(req):
    """Independent implementation: configs keyed WITHOUT observations; each maps to
    a set of observation tuples. Processed in topological (progress) order."""
    mem0 = tuple(req['memory'])
    progs = [tuple(tuple(i) for i in t) for t in req['threads']]
    n = len(progs)
    # per thread, prefix store counts: stores_done[p] = #stores among first p instrs
    init_cfg = (mem0, tuple((0, 0) for _ in range(n)))  # (pc, drained_count)
    # config -> set of obs tuples (one tuple of per-thread obs lists... as tuples)
    levels = defaultdict(dict)  # progress -> {cfg: set(obstuple)}
    levels[0][init_cfg] = {tuple(() for _ in range(n))}
    # per-thread drained counts needed to compute progress; buffer implied by
    # (pc, drained): buffer = stores[drained : executed], executed = #stores in prog[:pc]
    store_prefix = []
    for prog in progs:
        sp = [0]
        for instr in prog:
            sp.append(sp[-1] + (1 if instr[0] == 'store' else 0))
        store_prefix.append(sp)

    def stores_of(t):
        return [i for i in progs[t] if i[0] == 'store']

    outcomes = set()
    maxprog = sum(len(p) for p in progs) + sum(sum(1 for i in p if i[0]=='store') for p in progs)
    for prog_level in range(maxprog + 1):
        for (mem, tstates), obsset in levels.get(prog_level, {}).items():
            terminal = True
            for t in range(n):
                pc, drained = tstates[t]
                prog = progs[t]
                executed = store_prefix[t][pc]
                buf = stores_of(t)[drained:executed]
                if pc < len(prog):
                    terminal = False
                    instr = prog[pc]; op = instr[0]
                    if op == 'store':
                        ts2 = list(tstates); ts2[t] = (pc+1, drained)
                        tgt = levels[prog_level+1].setdefault((mem, tuple(ts2)), set())
                        tgt |= obsset
                    elif op == 'load':
                        _, a, w = instr
                        val = 0
                        for i in range(w):
                            ad = a+i; b = mem[ad]
                            for sinstr in reversed(buf):
                                _, sa, sw, sv = sinstr
                                if sa <= ad < sa+sw:
                                    b = (sv >> (8*(ad-sa))) & 0xFF; break
                            val |= b << (8*i)
                        ts2 = list(tstates); ts2[t] = (pc+1, drained)
                        tgt = levels[prog_level+1].setdefault((mem, tuple(ts2)), set())
                        tgt |= {o[:t]+(o[t]+(val,),)+o[t+1:] for o in obsset}
                    elif op == 'fence':
                        if not buf:
                            ts2 = list(tstates); ts2[t] = (pc+1, drained)
                            tgt = levels[prog_level+1].setdefault((mem, tuple(ts2)), set())
                            tgt |= obsset
                    elif op == 'xchg':
                        if not buf:
                            _, a, w, v = instr
                            old = sum(mem[a+i] << (8*i) for i in range(w))
                            m = list(mem)
                            for i in range(w): m[a+i] = (v >> (8*i)) & 0xFF
                            ts2 = list(tstates); ts2[t] = (pc+1, drained)
                            tgt = levels[prog_level+1].setdefault((tuple(m), tuple(ts2)), set())
                            tgt |= {o[:t]+(o[t]+(old,),)+o[t+1:] for o in obsset}
                if buf:
                    terminal = False
                    _, sa, sw, sv = buf[0]
                    m = list(mem)
                    for i in range(sw): m[sa+i] = (sv >> (8*i)) & 0xFF
                    ts2 = list(tstates); ts2[t] = (pc, drained+1)
                    tgt = levels[prog_level+1].setdefault((tuple(m), tuple(ts2)), set())
                    tgt |= obsset
            if terminal:
                for o in obsset:
                    outcomes.add((o, mem))
    return outcomes

if __name__ == '__main__':
    for line in sys.stdin:
        req = json.loads(line)
        res = alt(req)
        print(json.dumps({"outcomes":[{"reads":[list(o) for o in obs],"memory":list(m)} for obs,m in res]}))
