fails = 0
random.seed(int(sys.argv[1]) if len(sys.argv)>1 else 0)
for trial in range(300):
    nbytes = random.randint(1, 8)
    nthr = random.randint(1, 3)
    budget = 10
    ths = []
    for ti in range(nthr):
        k = random.randint(0, 4)
        if ti < nthr-1: k = min(k, budget - 0)
        k = min(k, budget)
        budget -= k
        p = []
        for _ in range(k):
            op = random.choice(['store','load','fence','xchg','store','load'])
            w = random.choice([1,2,4])
            if nbytes < w: op = 'fence' if random.random()<0.5 else 'store'; w = 1
            a = random.randint(0, nbytes-w)
            if op=='store': p.append(['store',a,w,random.randint(0,(1<<(8*w))-1)])
            elif op=='load': p.append(['load',a,w])
            elif op=='fence': p.append(['fence'])
            else: p.append(['xchg',a,w,random.randint(0,(1<<(8*w))-1)])
        ths.append(p)
